continue
end
if y.raid and z.move.ok~=nil and db.wanted()then
local Uv,Vv=pcall(db.step)
if not Uv then
e.log(1,XA[177],XA[736]..tostring(Vv))
task.wait(2)
end
if not Uv or Vv~=false then
continue
end
elseif db.run and not db.inRaid()then
pcall(db.finish)
end
if cb.awayAt and y.farmMode~=XA[487]then
if not cb.inRun()then
cb.awayAt=nil
else
local Wv=x.DEPTHS_AWAY-(os.clock()-cb.awayAt)
if Wv>0 then
e.now={icon=XA[11],title=XA[737]..math.ceil(Wv)..XA[281],text=XA[738],sub=XA[140]}
continue
end
cb.awayAt=nil
pcall(function()
J.Net.Event(XA[204]):FireServer(XA[520])
end)
e.log(1,XA[488],XA[739]..tostring(y.farmMode)..XA[356])
pcall(cb.finish,XA[740])
continue
end
end
if y.farmMode==XA[487]and z.move.ok~=nil then
local Xv,Yv=pcall(cb.step)
if not Xv then
e.log(1,XA[177],XA[741]..tostring(Yv))
task.wait(2)
end
continue
end
local Zv=J.busyElsewhere()
if Zv then
e.now={icon=XA[734],title=XA[742]..Zv,text=XA[743],sub=XA[140]}
continue
end
if z.move.ok==nil then
K.test()
continue
end
local _v=J.winReadyList()
if#_v>0 and y.fight and z.move.ok and N.allowed(_v[1])and not cb.inRun()then
local aw,bw=N.claim(_v[1])
if aw then
e.note(XA[44],XA[744].._v[1]..XA[745]..I.fmt(bw)..XA[746])
else
N.cool[_v[1]]=os.clock()+120
end
continue
end
if e.forceFight and z.move.ok then
local cw=e.forceFight
e.forceFight=nil
N.run(cw)
continue
end
local dw=J.EC:Active()
if dw and dw<=x.MAX_STAGE and y.fight and z.move.ok then
N.run(dw)
continue
end
if os.clock()>=Rv or not Tv then
Sv=V.compute()
Tv=V.choose(Sv)
Rv=os.clock()+2
end
if not Tv then
e.now={icon=XA[734],title=XA[747],text=XA[748],sub=XA[140]}
continue
end
if Tv.kind==XA[718]then
U.run(Sv.st)
Tv=nil
elseif Tv.kind==XA[386]then
if z.move.ok then
N.run(Tv.s)
else
e.now={icon=XA[259],title=XA[749],text=XA[750],sub=XA[140]}
end
Tv=nil
elseif Tv.kind==XA[479]then
local ew=Tv.pad
if M.onPad(ew)then
M.measure(ew)
e.now={icon=XA[38],title=XA[751]..ew.name..XA[300]..ew.mult,text=XA[752]..I.lvl(Sv.st)..XA[372]..I.fmt(M.lastRate or 0)..XA[753],sub=V.whyLine or XA[140]}
